import Darwin

/// Failures while reading a request; each maps onto an HTTP error response.
enum RequestError: Error {
    case malformed
    case headersTooLarge
    case bodyTooLarge
    case unsupportedTransferEncoding

    var response: HTTPResponse {
        switch self {
        case .malformed: HTTPResponse(400)
        case .headersTooLarge: HTTPResponse(431)
        case .bodyTooLarge: HTTPResponse(413)
        case .unsupportedTransferEncoding: HTTPResponse(501)
        }
    }
}

/// Blocking HTTP/1.1 connection over a connected socket. Owns and closes the descriptor.
final class Connection {
    static let maxHeaderSize = 64 * 1024
    private static let readChunkSize = 64 * 1024
    private static let headerTerminator: [UInt8] = Array("\r\n\r\n".utf8)

    private let fd: Int32
    private var buffer: [UInt8] = []

    init(fd: Int32) {
        self.fd = fd
    }

    deinit {
        close(fd)
    }

    /// Serves requests until the peer closes, asks to close, or an error occurs.
    func serve(router: Router) {
        while true {
            let request: HTTPRequest
            do {
                guard let next = try readRequest() else { return }
                request = next
            } catch let error as RequestError {
                _ = send(error.response.serialized(keepAlive: false))
                return
            } catch {
                return
            }

            let keepAlive = request.isKeepAlive
            let response = router.handle(request)
            guard send(response.serialized(keepAlive: keepAlive)), keepAlive else { return }
        }
    }

    // MARK: - Reading

    /// Reads the next request, or returns `nil` if the peer closed cleanly between requests.
    private func readRequest() throws -> HTTPRequest? {
        var scanFrom = 0
        let headerEnd: Int
        while true {
            if let end = findHeaderTerminator(from: scanFrom) {
                headerEnd = end
                break
            }
            guard buffer.count <= Self.maxHeaderSize else { throw RequestError.headersTooLarge }
            scanFrom = max(0, buffer.count - (Self.headerTerminator.count - 1))
            guard try fill() else {
                if buffer.isEmpty { return nil }
                throw RequestError.malformed
            }
        }

        var request = try parseHead(buffer[..<headerEnd])
        let bodyStart = headerEnd + Self.headerTerminator.count

        if request.header("transfer-encoding") != nil {
            throw RequestError.unsupportedTransferEncoding
        }
        let contentLength: Int
        if let raw = request.header("content-length") {
            guard let value = Int(raw), value >= 0 else { throw RequestError.malformed }
            contentLength = value
        } else {
            contentLength = 0
        }
        guard contentLength <= Router.maxValueSize else { throw RequestError.bodyTooLarge }

        let requestEnd = bodyStart + contentLength
        if buffer.count < requestEnd {
            buffer.reserveCapacity(requestEnd)
        }
        while buffer.count < requestEnd {
            guard try fill() else { throw RequestError.malformed }
        }

        request.body = Array(buffer[bodyStart..<requestEnd])
        buffer.removeFirst(requestEnd)
        return request
    }

    private func findHeaderTerminator(from start: Int) -> Int? {
        let terminator = Self.headerTerminator
        guard buffer.count >= terminator.count else { return nil }
        var i = start
        while i <= buffer.count - terminator.count {
            if buffer[i] == terminator[0], buffer[i + 1] == terminator[1],
               buffer[i + 2] == terminator[2], buffer[i + 3] == terminator[3] {
                return i
            }
            i += 1
        }
        return nil
    }

    private func parseHead(_ bytes: ArraySlice<UInt8>) throws -> HTTPRequest {
        // Header bytes outside UTF-8 are replaced; routing only needs ASCII.
        let text = String(decoding: bytes, as: UTF8.self)
        var lines = text.split(separator: "\r\n", omittingEmptySubsequences: false)[...]
        guard let requestLine = lines.popFirst() else { throw RequestError.malformed }

        let parts = requestLine.split(separator: " ", omittingEmptySubsequences: true)
        guard parts.count == 3, parts[2].hasPrefix("HTTP/1.") else { throw RequestError.malformed }

        var headers: [(name: String, value: String)] = []
        for line in lines {
            guard let colon = line.firstIndex(of: ":") else { throw RequestError.malformed }
            let name = line[..<colon].lowercased()
            let value = line[line.index(after: colon)...].trimmingWhitespace()
            headers.append((name: name, value: value))
        }

        return HTTPRequest(
            method: String(parts[0]),
            target: String(parts[1]),
            version: String(parts[2]),
            headers: headers,
            body: []
        )
    }

    /// Appends available bytes to the buffer. Returns `false` on EOF.
    private func fill() throws -> Bool {
        var chunk = [UInt8](repeating: 0, count: Self.readChunkSize)
        while true {
            let n = chunk.withUnsafeMutableBytes { recv(fd, $0.baseAddress, $0.count, 0) }
            if n > 0 {
                buffer.append(contentsOf: chunk[..<n])
                return true
            }
            if n == 0 { return false }
            if errno == EINTR { continue }
            throw SocketError.system("recv", errno)
        }
    }

    // MARK: - Writing

    /// Writes all bytes. Returns `false` if the peer went away.
    private func send(_ bytes: [UInt8]) -> Bool {
        bytes.withUnsafeBytes { raw in
            var offset = 0
            while offset < raw.count {
                let n = Darwin.send(fd, raw.baseAddress! + offset, raw.count - offset, 0)
                if n > 0 {
                    offset += n
                } else if n < 0 && errno == EINTR {
                    continue
                } else {
                    return false
                }
            }
            return true
        }
    }
}

private extension Substring {
    func trimmingWhitespace() -> String {
        let isSpace: (Character) -> Bool = { $0 == " " || $0 == "\t" }
        guard let first = firstIndex(where: { !isSpace($0) }),
              let last = lastIndex(where: { !isSpace($0) })
        else { return "" }
        return String(self[first...last])
    }
}

/// A parsed HTTP/1.x request.
struct HTTPRequest {
    var method: String
    var target: String
    var version: String
    /// Header names are lower-cased.
    var headers: [(name: String, value: String)]
    var body: [UInt8]

    func header(_ name: String) -> String? {
        headers.first { $0.name == name }?.value
    }

    /// Whether the client asked to reuse the connection after this request.
    var isKeepAlive: Bool {
        let connection = header("connection")?.lowercased()
        if version == "HTTP/1.0" {
            return connection == "keep-alive"
        }
        return connection != "close"
    }
}

/// An HTTP response with a fully materialised body.
struct HTTPResponse {
    var status: Int
    var body: [UInt8] = []
    var contentType: String?

    init(_ status: Int, body: [UInt8] = [], contentType: String? = nil) {
        self.status = status
        self.body = body
        self.contentType = contentType
    }

    func serialized(keepAlive: Bool) -> [UInt8] {
        var head = "HTTP/1.1 \(status) \(Self.reasonPhrase(status))\r\n"
        if let contentType {
            head += "Content-Type: \(contentType)\r\n"
        }
        head += "Content-Length: \(body.count)\r\n"
        head += "Connection: \(keepAlive ? "keep-alive" : "close")\r\n\r\n"
        return Array(head.utf8) + body
    }

    static func reasonPhrase(_ status: Int) -> String {
        switch status {
        case 200: "OK"
        case 201: "Created"
        case 204: "No Content"
        case 400: "Bad Request"
        case 404: "Not Found"
        case 405: "Method Not Allowed"
        case 408: "Request Timeout"
        case 413: "Content Too Large"
        case 431: "Request Header Fields Too Large"
        case 501: "Not Implemented"
        default: "Unknown"
        }
    }
}

import os

/// Thread-safe in-memory key-value store shared by all connection threads.
final class KeyValueStore: Sendable {
    enum PutResult {
        case created
        case replaced
    }

    private let storage = OSAllocatedUnfairLock<[String: [UInt8]]>(initialState: [:])

    func get(_ key: String) -> [UInt8]? {
        storage.withLock { $0[key] }
    }

    func put(_ key: String, value: [UInt8]) -> PutResult {
        storage.withLock { $0.updateValue(value, forKey: key) == nil ? .created : .replaced }
    }

    /// Returns `true` if the key existed and was removed.
    func delete(_ key: String) -> Bool {
        storage.withLock { $0.removeValue(forKey: key) != nil }
    }

    /// All keys, sorted ascending by byte value.
    func sortedKeys() -> [String] {
        let keys = storage.withLock { Array($0.keys) }
        return keys.sorted { $0.utf8.lexicographicallyPrecedes($1.utf8) }
    }
}

/// Maps requests onto store operations. Free of I/O.
struct Router {
    static let maxValueSize = 1 << 20

    let store: KeyValueStore

    func handle(_ request: HTTPRequest) -> HTTPResponse {
        // Paths never carry a query string per the spec, but strip one defensively.
        let path = request.target.split(separator: "?", maxSplits: 1, omittingEmptySubsequences: false)
            .first.map(String.init) ?? request.target
        let method = request.method

        switch path {
        case "/health":
            guard method == "GET" else { return HTTPResponse(405) }
            return HTTPResponse(200, body: Array("ok".utf8), contentType: "text/plain")

        case "/kv":
            guard method == "GET" else { return HTTPResponse(405) }
            return listKeys()

        case let p where p.hasPrefix("/kv/"):
            let key = String(p.dropFirst("/kv/".count))
            guard Self.isValidKey(key) else { return HTTPResponse(400) }
            return handleKey(method: method, key: key, body: request.body)

        default:
            return HTTPResponse(404)
        }
    }

    private func handleKey(method: String, key: String, body: [UInt8]) -> HTTPResponse {
        switch method {
        case "GET":
            guard let value = store.get(key) else { return HTTPResponse(404) }
            return HTTPResponse(200, body: value, contentType: "application/octet-stream")
        case "PUT":
            switch store.put(key, value: body) {
            case .created: return HTTPResponse(201)
            case .replaced: return HTTPResponse(200)
            }
        case "DELETE":
            return store.delete(key) ? HTTPResponse(204) : HTTPResponse(404)
        default:
            return HTTPResponse(405)
        }
    }

    private func listKeys() -> HTTPResponse {
        // Keys are restricted to [A-Za-z0-9_-], so they never need JSON escaping.
        let json = "[" + store.sortedKeys().map { "\"\($0)\"" }.joined(separator: ",") + "]"
        return HTTPResponse(200, body: Array(json.utf8), contentType: "application/json")
    }

    static func isValidKey(_ key: String) -> Bool {
        let bytes = key.utf8
        guard (1...64).contains(bytes.count) else { return false }
        return bytes.allSatisfy { byte in
            switch byte {
            case UInt8(ascii: "A")...UInt8(ascii: "Z"),
                 UInt8(ascii: "a")...UInt8(ascii: "z"),
                 UInt8(ascii: "0")...UInt8(ascii: "9"),
                 UInt8(ascii: "_"), UInt8(ascii: "-"):
                true
            default:
                false
            }
        }
    }
}

import Darwin
import Foundation

enum SocketError: Error, CustomStringConvertible {
    case system(String, Int32)

    var description: String {
        switch self {
        case let .system(call, code):
            "\(call) failed: \(String(cString: strerror(code)))"
        }
    }
}

/// Accepts TCP connections on 127.0.0.1 and serves each on its own thread.
///
/// A thread per connection keeps request handling simple, blocking code while
/// comfortably supporting the required number of simultaneous clients.
struct Server: Sendable {
    let port: UInt16
    let store: KeyValueStore
    var backlog: Int32 = 1024
    /// Idle connections are dropped after this many seconds without data.
    var readTimeout = 30

    func run() throws -> Never {
        signal(SIGPIPE, SIG_IGN)
        let listener = try makeListener()
        let router = Router(store: store)

        while true {
            let client = accept(listener, nil, nil)
            if client < 0 {
                if errno == EINTR || errno == ECONNABORTED { continue }
                if errno == EMFILE || errno == ENFILE {
                    usleep(10_000)
                    continue
                }
                throw SocketError.system("accept", errno)
            }
            configure(client: client)

            let thread = Thread {
                Connection(fd: client).serve(router: router)
            }
            thread.stackSize = 1 << 20
            thread.start()
        }
    }

    private func makeListener() throws -> Int32 {
        let fd = socket(AF_INET, SOCK_STREAM, 0)
        guard fd >= 0 else { throw SocketError.system("socket", errno) }

        var on: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &on, socklen_t(MemoryLayout<Int32>.size))

        var addr = sockaddr_in()
        addr.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_port = port.bigEndian
        addr.sin_addr.s_addr = inet_addr("127.0.0.1")

        let bound = withUnsafePointer(to: &addr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }
        guard bound == 0 else {
            let code = errno
            close(fd)
            throw SocketError.system("bind", code)
        }
        guard listen(fd, backlog) == 0 else {
            let code = errno
            close(fd)
            throw SocketError.system("listen", code)
        }
        return fd
    }

    private func configure(client fd: Int32) {
        var on: Int32 = 1
        setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &on, socklen_t(MemoryLayout<Int32>.size))
        setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &on, socklen_t(MemoryLayout<Int32>.size))
        var timeout = timeval(tv_sec: readTimeout, tv_usec: 0)
        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, socklen_t(MemoryLayout<timeval>.size))
    }
}

import Foundation

func fail(_ message: String, code: Int32) -> Never {
    FileHandle.standardError.write(Data("kvhttp: \(message)\n".utf8))
    exit(code)
}

let arguments = CommandLine.arguments
guard arguments.count == 2, let port = UInt16(arguments[1]), port > 0 else {
    fail("usage: \(arguments.first ?? "app") <port>", code: 2)
}

do {
    try Server(port: port, store: KeyValueStore()).run()
} catch {
    fail("\(error)", code: 1)
}
